#!/usr/bin/env python3
"""Produce a deterministic JSON fingerprint for a small UTF-8 text file."""

from __future__ import annotations

import hashlib
import json
import sys

MAX_INPUT_BYTES = 4096


def fail(message: str) -> int:
    sys.stderr.write(f"error: {message}\n")
    return 1


def main(argv: list[str] | None = None) -> int:
    arguments = sys.argv[1:] if argv is None else argv
    if len(arguments) != 1:
        return fail("expected exactly one file path argument")

    try:
        with open(arguments[0], "rb") as input_file:
            data = input_file.read(MAX_INPUT_BYTES + 1)
    except OSError:
        return fail("unable to read input file")

    if len(data) > MAX_INPUT_BYTES:
        return fail("input exceeds 4096 bytes")

    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        return fail("input is not valid UTF-8")

    result = {
        "byte_count": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "text": text,
    }
    output = json.dumps(
        result,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    sys.stdout.buffer.write(output.encode("utf-8") + b"\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
